const root='C:/Users/HP/Downloads/SunuPermis';
const pages=[{name:'Accueil',file:root+'/index.html'},{name:'Administration',file:root+'/admin.html'},{name:'Carte du Sénégal',file:root+'/carte-senegal.html'},{name:'Code de la route',file:root+'/code-route.html'},{name:'Conduite',file:root+'/conduire.html'},{name:'Conseils examen',file:root+'/conseils-examen.html'},{name:'Examen blanc',file:root+'/examen.html'},{name:'Glossaire',file:root+'/glossaire.html'},{name:'Manœuvres',file:root+'/manoeuvres.html'},{name:'Offres',file:root+'/offres.html'},{name:'Choix du permis',file:root+'/permis.html'},{name:'Profil',file:root+'/profil.html'}];
const itemSchema=JSON.stringify({type:'object',properties:{target:{type:'string'},summary:{type:'string'},findings:{type:'array',items:{type:'object',properties:{severity:{type:'string',enum:['critique','élevée','moyenne','faible','information']},category:{type:'string'},issue:{type:'string'},evidence:{type:'string'},proposed_fix:{type:'string'},confidence:{type:'string',enum:['élevée','moyenne','faible']}},required:['severity','category','issue','evidence','proposed_fix','confidence']}}},required:['target','summary','findings']});
const results=await parallel('Revue des 12 pages manquantes',()=>pages.map(page=>agent('Examine exactement le fichier HTML fourni pour la page «'+page.name+'» de SunuPermis. Le fichier est fourni comme input nommé page.html : lis son contenu fourni, pas un chemin supposé. Audit en lecture seule : balisage/DOM, HTML mal imbriqué, boutons et formulaires, labels et ARIA, identifiants/références, scripts inline et couleurs inline. Signale seulement les défauts vérifiables à partir de ce fichier, avec preuve ligne/extrait court, gravité, correctif minimal et confiance. Ne juge pas les feuilles CSS ou scripts externes absents; mentionne explicitement si la page ne révèle pas de défaut. Ne modifie aucun fichier. Retourne le schéma en français.',{brief:'Auditer la page '+page.name,input_files:[{path:page.file,name:'page.html'}],sandbox:'shared',effort_level:'standard'})),{schema:itemSchema});
const successful=results.filter(x=>x.ok).map(x=>x.value);
const failures=results.map((x,i)=>x.ok?null:{target:pages[i].name,code:x.error.code,message:x.error.message}).filter(Boolean);
const reducerSchema=JSON.stringify({type:'object',properties:{summary:{type:'string'},findings:{type:'array',items:{type:'object',properties:{target:{type:'string'},severity:{type:'string',enum:['critique','élevée','moyenne','faible','information']},category:{type:'string'},issue:{type:'string'},evidence:{type:'string'},proposed_fix:{type:'string'},confidence:{type:'string',enum:['élevée','moyenne','faible']},duplicate_of:{type:'string'}},required:['target','severity','category','issue','evidence','proposed_fix','confidence','duplicate_of']}},coverage_gaps:{type:'array',items:{type:'string'}}},required:['summary','findings','coverage_gaps']});
const reduced=await agent('Déduplique et synthétise les constats des 12 pages ci-dessous. N’ajoute aucun problème non prouvé, garde les preuves et indique explicitement les fichiers sans constat ainsi que les échecs de couverture. Résultats: '+JSON.stringify(successful)+'; échecs: '+JSON.stringify(failures),{brief:'Synthétiser les 12 pages restantes',sandbox:'shared',effort_level:'standard',schema:reducerSchema});
return {audited_pages:successful.length,failures,reduced:reduced.ok?reduced.value:null,reducer_failure:reduced.ok?null:{code:reduced.error.code,message:reduced.error.message}};

